import{_ as n,y as d,a as i,o as l,a2 as r,D as a,g as e,I as s}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"GDPR Data Requests","description":"","frontmatter":{},"headers":[],"relativePath":"customer/gdpr-data-requests.md","filePath":"customer/gdpr-data-requests.md","lastUpdated":1789441803000}'),u={name:"customer/gdpr-data-requests.md"};function g(h,t,c,m,p,q){const o=d("ImagePopup");return l(),i("div",null,[t[4]||(t[4]=r('<h1 id="gdpr-data-requests" tabindex="-1">GDPR Data Requests <a class="header-anchor" href="#gdpr-data-requests" aria-label="Permalink to &quot;GDPR Data Requests&quot;">​</a></h1><p>Under the GDPR (General Data Protection Regulation), customers can ask you to correct or delete the personal data you hold about them. Bagisto lets customers send these requests from their account and download a copy of their data. You see the requests under <strong>Customers &gt;&gt; GDPR Data Requests</strong>, and the customer receives an email when you change a request&#39;s status. The change to the customer&#39;s data is made by you.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Customers see <strong>GDPR Requests</strong> in their account only while <strong>Enable GDPR</strong> is on for the channel and language they&#39;re browsing. See <a href="./../configure/gdpr.html">GDPR</a>. The list in the admin panel is always available.</p><h2 id="what-customers-do-on-the-storefront" tabindex="-1">What customers do on the storefront <a class="header-anchor" href="#what-customers-do-on-the-storefront" aria-label="Permalink to &quot;What customers do on the storefront&quot;">​</a></h2><p>Signed-in customers open <strong>GDPR Requests</strong> in <strong>My Account</strong>. The <strong>GDPR Data Requests</strong> page lists their requests with the <strong>ID</strong>, <strong>Type</strong>, <strong>Date</strong>, <strong>Message</strong> and <strong>Status</strong>.</p><h3 id="download-their-data" tabindex="-1">Download their data <a class="header-anchor" href="#download-their-data" aria-label="Permalink to &quot;Download their data&quot;">​</a></h3><ul><li><strong>PDF</strong> downloads a PDF with their account information, addresses and orders.</li><li><strong>HTML</strong> opens the same information in the browser.</li></ul><h3 id="send-a-request" tabindex="-1">Send a request <a class="header-anchor" href="#send-a-request" aria-label="Permalink to &quot;Send a request&quot;">​</a></h3><ol><li>Go to <strong>My Account &gt;&gt; GDPR Requests</strong>.</li><li>Click <strong>Create Request</strong>. The <strong>Create New Request</strong> dialog opens.</li><li>Choose the <strong>Type</strong>: <strong>Update</strong> to have their data corrected, or <strong>Delete</strong> to have it deleted.</li><li>Write the <strong>Message</strong>, saying what should change. It can be up to 500 characters long.</li><li>Click <strong>Save</strong>.</li></ol><p>The request is listed as <strong>Pending</strong>. The customer receives an email about the request, and so does the admin email address set in <a href="./../configure/email-settings.html">Email Settings</a>.</p><h3 id="revoke-a-request" tabindex="-1">Revoke a request <a class="header-anchor" href="#revoke-a-request" aria-label="Permalink to &quot;Revoke a request&quot;">​</a></h3><p>While a request is <strong>Pending</strong>, the customer can click <strong>Revoke</strong> on its row to withdraw it. Its status changes to <strong>Revoked</strong>, and the customer and the admin receive an email. <strong>Revoke</strong> is greyed out on any request that isn&#39;t <strong>Pending</strong>.</p><h2 id="handle-requests-in-the-admin-panel" tabindex="-1">Handle requests in the admin panel <a class="header-anchor" href="#handle-requests-in-the-admin-panel" aria-label="Permalink to &quot;Handle requests in the admin panel&quot;">​</a></h2><p>Go to <strong>Customers &gt;&gt; GDPR Data Requests</strong>.</p><p>The list shows each request&#39;s <strong>ID</strong>, <strong>Customer Name</strong>, <strong>Status</strong>, <strong>Type</strong>, <strong>Message</strong> and <strong>Created At</strong>. <strong>Type</strong> reads <strong>Delete</strong> for a delete request and <strong>Edit</strong> for an update request.</p>',16)),a(o,{src:"/images/customer/gdpr-data-requests.png",alt:"GDPR data requests list with a pending update request"}),t[5]||(t[5]=r('<ul><li><strong>Search:</strong> type in the search box to find requests by ID, customer name, status, type or message.</li><li><strong>Filter:</strong> click <strong>Filter</strong> and filter by <strong>ID</strong>, <strong>Customer Name</strong>, <strong>Status</strong>, <strong>Type</strong> or <strong>Created At</strong>.</li><li><strong>Export:</strong> click <strong>Export</strong> to download the list as CSV, XLS or XLSX.</li><li><strong>Edit</strong> (the pencil) and <strong>Delete</strong> (the bin) are at the end of each row.</li></ul><h3 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Use it when</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>The request is new. Customers can revoke a request only while it&#39;s pending.</td></tr><tr><td><strong>Processing</strong></td><td>You&#39;re working on the request.</td></tr><tr><td><strong>Completed</strong></td><td>You&#39;ve made the change the customer asked for.</td></tr><tr><td><strong>Declined</strong></td><td>You won&#39;t make the change, for example because you must keep order records by law.</td></tr><tr><td><strong>Revoked</strong></td><td>The customer withdrew the request.</td></tr></tbody></table><h3 id="update-a-request" tabindex="-1">Update a request <a class="header-anchor" href="#update-a-request" aria-label="Permalink to &quot;Update a request&quot;">​</a></h3>',4)),e("ol",null,[t[1]||(t[1]=e("li",null,[e("p",null,[s("Go to "),e("strong",null,"Customers >> GDPR Data Requests"),s(".")])],-1)),t[2]||(t[2]=e("li",null,[e("p",null,[s("Click the pencil on the request's row. The "),e("strong",null,"Edit GDPR Data Request"),s(" dialog opens.")])],-1)),e("li",null,[t[0]||(t[0]=e("p",null,[s("Choose the "),e("strong",null,"Status"),s(".")],-1)),a(o,{src:"/images/customer/gdpr-edit.png",alt:"Edit GDPR Data Request dialog with Status, Type and Message"})]),t[3]||(t[3]=e("li",null,[e("p",null,[s("Click "),e("strong",null,"Save"),s(". The customer receives an email with the new status.")])],-1))]),t[6]||(t[6]=r('<p>The dialog also shows the request&#39;s <strong>Type</strong>, which you can&#39;t change, and the <strong>Message</strong>. Leave the message as it is, because it holds the customer&#39;s request.</p><h3 id="a-status-doesn-t-change-the-data" tabindex="-1">A status doesn&#39;t change the data <a class="header-anchor" href="#a-status-doesn-t-change-the-data" aria-label="Permalink to &quot;A status doesn&#39;t change the data&quot;">​</a></h3><p>Changing a request&#39;s status doesn&#39;t update or delete anything. Make the change yourself on the customer&#39;s page under <strong>Customers &gt;&gt; Customers</strong>:</p><ul><li><strong>An update request:</strong> correct the details with <strong>Edit</strong> on the <strong>Customer</strong> card, or edit the addresses. Then set the request to <strong>Completed</strong>. See <a href="./create-customer.html#edit-customer-details">Edit customer details</a>.</li><li><strong>A delete request:</strong> set the request to <strong>Completed</strong> first, and wait until the customer has received the email. Then click <strong>Delete Account</strong>. Deleting the account also deletes the customer&#39;s GDPR requests, and their orders stay under <strong>Sales &gt;&gt; Orders</strong>. See <a href="./create-customer.html#delete-the-account">Delete the account</a>.</li></ul><h3 id="delete-a-request" tabindex="-1">Delete a request <a class="header-anchor" href="#delete-a-request" aria-label="Permalink to &quot;Delete a request&quot;">​</a></h3><ol><li>Go to <strong>Customers &gt;&gt; GDPR Data Requests</strong>.</li><li>Click the bin on the request&#39;s row.</li><li>Click <strong>Agree</strong> to confirm.</li></ol><p>This removes the request from the list. It doesn&#39;t change the customer&#39;s account.</p>',7))])}const P=n(u,[["render",g]]);export{f as __pageData,P as default};
